UPDATE phases ph SET status=(SELECT CASE WHEN count(*) FILTER (WHERE t.status<>'cancelled')=0 THEN 'pending' WHEN count(*) FILTER (WHERE t.status NOT IN ('done','cancelled'))=0 THEN 'completed' WHEN count(*) FILTER (WHERE t.status='blocked')>0 THEN 'blocked' WHEN count(*) FILTER (WHERE t.status='in_progress')>0 THEN 'in_progress' ELSE 'pending' END FROM tasks t WHERE t.phase_id=ph.id),updated_at=now() WHERE ph.plan_id=$1 AND ph.status<>'removed'
